create extension if not exists pgcrypto;
create table if not exists classes(id uuid primary key default gen_random_uuid(),name text not null,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists groups(id uuid primary key default gen_random_uuid(),class_id uuid not null references classes(id) on delete cascade,name text not null,position int not null default 0,created_at timestamptz not null default now());
create table if not exists members(id uuid primary key default gen_random_uuid(),class_id uuid not null references classes(id) on delete cascade,name text not null,created_at timestamptz not null default now());
create table if not exists member_weights(member_id uuid not null references members(id) on delete cascade,group_id uuid not null references groups(id) on delete cascade,percent numeric(5,2) not null default 0 check(percent between 0 and 100),primary key(member_id,group_id));
create table if not exists history(id bigint generated by default as identity primary key,class_id uuid not null references classes(id) on delete cascade,member_id uuid references members(id) on delete set null,group_id uuid references groups(id) on delete set null,created_at timestamptz not null default now());
create table if not exists admins(user_id uuid primary key references auth.users(id) on delete cascade);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admins where user_id=auth.uid()); $$;
alter table classes enable row level security;alter table groups enable row level security;alter table members enable row level security;alter table member_weights enable row level security;alter table history enable row level security;alter table admins enable row level security;
drop policy if exists class_read on classes;drop policy if exists class_admin on classes;create policy class_read on classes for select to anon,authenticated using(is_active or public.is_admin());create policy class_admin on classes for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists group_read on groups;drop policy if exists group_admin on groups;create policy group_read on groups for select to anon,authenticated using(true);create policy group_admin on groups for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists member_read on members;drop policy if exists member_admin on members;create policy member_read on members for select to anon,authenticated using(true);create policy member_admin on members for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists weight_read on member_weights;drop policy if exists weight_admin on member_weights;create policy weight_read on member_weights for select to anon,authenticated using(true);create policy weight_admin on member_weights for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists history_insert on history;drop policy if exists history_read on history;drop policy if exists history_delete on history;create policy history_insert on history for insert to anon,authenticated with check(true);create policy history_read on history for select to authenticated using(public.is_admin());create policy history_delete on history for delete to authenticated using(public.is_admin());
